import { ArrowLeft, ArrowRight, CheckCircle2, Clock3, Compass, IndianRupee, LoaderCircle, Map, Navigation, Route, Ruler, Truck } from 'lucide-react';
import { useState } from 'react';
import { Link } from 'react-router-dom';
import { estimateRoute } from '../../services/api';

export default function RouteEstimatePage() {
    const [pickup, setPickup] = useState('Guntur');
    const [destination, setDestination] = useState('Vijayawada');
    const [route, setRoute] = useState(null);
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);
    const fullMapUrl = route ? `https://www.google.com/maps/dir/?api=1&origin=${encodeURIComponent(route.pickup)}&destination=${encodeURIComponent(route.destination)}` : '';
    async function submit(event) {
        event.preventDefault();
        setError('');
        setLoading(true);
        try { const result = await estimateRoute(pickup, destination); setRoute(result.route); }
        catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Unable to estimate route'); }
        finally { setLoading(false); }
    }
    return <main className="route-estimate-page optimize-routes-page"><div className="route-estimate-container"><div className="route-estimate-breadcrumb"><Link to="/dashboard/logistics"><ArrowLeft size={15}/> Logistics command</Link><span>ROUTES / PLANNING DESK</span></div><header className="route-estimate-hero optimize-routes-hero"><div><p className="route-estimate-kicker"><Compass size={14}/> Route optimization</p><h1>Optimize routes for faster and cost-effective delivery.</h1><p>Plan the cleanest handoff between your pickup point and destination before a vehicle leaves the yard.</p></div><div className="route-estimate-hero-mark"><Route size={30}/><span>ROUTE<br/>OPTIMIZER</span></div></header><div className="optimize-routes-workspace"><form className="route-estimate-form optimize-routes-form" onSubmit={submit}><div className="route-estimate-form-heading"><div><span>ROUTE INPUT</span><h2>Build a delivery route</h2><p>Enter the starting point and final destination.</p></div><Navigation size={20}/></div><label><span>Starting Point</span><div className="route-estimate-input"><Map size={16}/><input value={pickup} onChange={(event) => setPickup(event.target.value)} placeholder="e.g. Guntur" required /></div></label><label><span>Destination</span><div className="route-estimate-input"><Map size={16}/><input value={destination} onChange={(event) => setDestination(event.target.value)} placeholder="e.g. Vijayawada" required /></div></label>{error && <p className="route-estimate-error" role="alert">{error}</p>}<button className="route-estimate-submit optimize-routes-submit" type="submit" disabled={loading}>{loading ? <><LoaderCircle className="route-spin" size={16}/> Optimizing route...</> : <>Optimize Route <ArrowRight size={16}/></>}</button><p className="route-estimate-note">Uses FarmDirect's local distance and delivery cost estimate.</p></form><section className={`optimize-route-result ${route ? 'has-route' : ''}`}>{route ? <><div className="optimize-result-top"><div><span>OPTIMIZED ROUTE</span><h2>Ready for dispatch</h2></div><CheckCircle2 size={20}/></div><div className="optimize-route-map"><div className="optimize-map-road optimize-map-road-main" /><div className="optimize-map-road optimize-map-road-alt" /><span className="optimize-map-node node-start">1</span><span className="optimize-map-node node-mid">2</span><span className="optimize-map-node node-end">3</span><span className="optimize-map-label label-start">{route.pickup}</span><span className="optimize-map-label label-mid">Transfer</span><span className="optimize-map-label label-end">{route.destination}</span><span className="optimize-map-truck"><Truck size={17}/></span></div><div className="optimize-route-stop-list"><div><b>1</b><span><strong>{route.pickup}</strong><small>Pickup location</small></span></div><ArrowRight size={15}/><div><b>2</b><span><strong>Transfer point</strong><small>Optimized stop</small></span></div><ArrowRight size={15}/><div><b>3</b><span><strong>{route.destination}</strong><small>Final dropoff</small></span></div></div><div className="optimize-route-metrics"><div><Ruler size={15}/><span>Total Distance<strong>{route.distance_km} km</strong></span></div><div><Clock3 size={15}/><span>Estimated Time<strong>{formatEta(route.eta_hours)}</strong></span></div><div><IndianRupee size={15}/><span>Estimated Cost<strong>₹{Number(route.estimated_cost).toLocaleString('en-IN')}</strong></span></div></div><div className="optimize-route-saving">✓ Route optimized for the fastest available handoff <a href={fullMapUrl} target="_blank" rel="noreferrer">Open in Maps <ArrowRight size={13}/></a></div></> : <div className="optimize-route-empty"><Route size={28}/><span>ROUTE PREVIEW</span><h2>Your optimized route will appear here.</h2><p>Enter your start and destination to see stops, distance, delivery time, and cost.</p></div>}</section></div></div></main>;
}

function formatEta(hours) { const totalMinutes = Math.round(Number(hours || 0) * 60); const wholeHours = Math.floor(totalMinutes / 60); const minutes = totalMinutes % 60; return `${wholeHours}h${minutes ? ` ${minutes}m` : ''}`; }
